TLM.f("Sancti/10-23r",{"officium":"S. Antonii Mariæ Claret Episcopi Confessoris","rule":["vide C4;","Gloria"],"fallback":"Commune/C4","from":{"GradualeP":"Commune/C4","Tractus":"Commune/C4"},"sections":{"Introitus":[{"k":"ref","la":"Ps 131:9-10"},{"k":"text","la":"Sacerdótes tui, Dómine, induántur justítiam, et sancti tui exsúltent. Propter David servum tuum non avértas fáciem christi tui."},{"k":"ref","la":"Ps 131:1"},{"k":"text","la":"Meménto, Dómine, David, et omnis mansuetúdinis ejus:"},{"k":"macro","name":"Gloria"},{"k":"text","la":"Sacerdótes tui, Dómine, induántur justítiam, et sancti tui exsúltent. Propter David servum tuum non avértas fáciem christi tui."}],"Oratio":[{"k":"text","la":"Deus, qui beátum Antónium Maríam Confessórem tuum atque Pontíficem, apostólicis virtútibus sublimásti, et per eum novas in Ecclésia clericórum ac vírginum famílias collegísti: concéde, quǽsumus; ut, eius dirigéntibus mónitis ac suffragántibus méritis, animárum salútem quǽrere iúgiter studeámus."},{"k":"macro","name":"Per Dominum"}],"Lectio":[{"k":"text","la":"Léctio Epístolæ beáti Pauli Apóstoli ad Hebrǽos"},{"k":"ref","la":"Heb 7:23-27"},{"k":"text","la":"Fratres : Plures facti sunt sacerdótes, idcírco quod morte prohiberéntur permanére : Iesus autem, eo quod máneat in ætérnum, sempitérnum habet sacerdótium. Unde et salváre in perpétuum potest accedéntes per semetípsum ad Deum : semper vivens ad interpellándum pro nobis. Talis enim decébat, ut nobis esset póntifex, sanctus, ínnocens, impollútus, segregátus a peccatóribus, et excélsior cælis factus : qui non habet necessitátem cotídie, quemádmodum sacerdótes, prius pro suis delíctis hóstias offérre, deínde pro pópuli : hoc enim fecit semel, seípsum offeréndo, Jesus Christus, Dóminus noster."}],"Graduale":[{"k":"ref","la":"Ps 131:16-17"},{"k":"text","la":"Sacerdótes ejus índuam salutári, et sancti ejus exsultatióne exsultábunt.","mark":"V"},{"k":"text","la":"Illuc prodúcam cornu David; parávi lucérnam christo meo. Allelúia, allelúia.","mark":"V"},{"k":"ref","la":"Ps 109:4"},{"k":"text","la":"Jurávit Dóminus, et non pœnitébit eum: Tu es sacérdos in ætérnum secúndum órdinem Melchísedech. Allelúia.","mark":"V"}],"GradualeP":[{"k":"text","la":"Allelúja, allelúja."},{"k":"ref","la":"Ps 109:4"},{"k":"text","la":"Tu es sacérdos in ætérnum, secúndum órdinem Melchísedech. Allelúja."},{"k":"text","la":"Hic est sacérdos, quem coronávit Dóminus. Allelúja.","mark":"V"}],"Tractus":[{"k":"ref","la":"Eccli 44:16"},{"k":"text","la":"Ecce sacérdos magnus, qui in diébus suis plácuit Deo."},{"k":"ref","la":"Eccli 44:20"},{"k":"text","la":"Non est invéntus símilis illi, qui conserváret legem Excélsi."},{"k":"ref","la":"Ps 111:1-3"},{"k":"text","la":"Beátus vir, qui timet Dóminum: in mandátis ejus cupit nimis."},{"k":"text","la":"Potens in terra erit semen ejus: generátio rectórum benedicétur.","mark":"V"},{"k":"text","la":"Glória et divítiæ in domo ejus: et justítia ejus manet in sǽculum sǽculi.","mark":"V"}],"Evangelium":[{"k":"text","la":"Lectio sancti Evangelii secundum Matthǽum"},{"k":"ref","la":"Matt 24:42-47"},{"k":"text","la":"In illo témpore: Dixit Jesus discípulis suis: Vigiláte ergo, quia nescítis qua hora Dóminus vester ventúrus sit. Illud autem scitóte, quóniam si sciret paterfamílias qua hora fur ventúrus esset, vigiláret útique, et non síneret pérfodi domum suam. Ideo et vos estóte paráti: quia qua nescítis hora Fílius hóminis ventúrus est. Quis, putas, est fidélis servus, et prudens, quem constítuit dóminus suus super famíliam suam ut det illis cibum in témpore? Beátus ille servus, quem cum vénerit dóminus ejus, invénerit sic faciéntem. Amen dico vobis, quóniam super ómnia bona sua constítuet eum."}],"Offertorium":[{"k":"ref","la":"Ps 88:25"},{"k":"text","la":"Véritas mea et misericórdia mea cum ipso: et in nómine meo exaltábitur cornu ejus. (Allelúja.)"}],"Secreta":[{"k":"text","la":"Sancti Antónii Maríæ Confessóris tui atque Pontíficis, quǽsumus, Dómine, ánnua sollémnitas pietáti tuæ nos reddat accéptos: ut, per hæc piæ placatiónis offícia, et illum beáta retribútio comitétur, ei nobis grátiæ tuæ dona concíliet."},{"k":"macro","name":"Per Dominum"}],"Communio":[{"k":"ref","la":"Matt 24:46-47"},{"k":"text","la":"Beátus servus, quem, cum vénerit dóminus, invénerit vigilántem: amen, dico vobis, super ómnia bona sua constítuet eum. (Allelúja.)"}],"Postcommunio":[{"k":"text","la":"Deus, fidélium remunerátor animárum: præsta; ut, beáti Antónii Maríæ Confessóris tui atque Pontíficis, cujus venerándam celebrámus festivitátem, précibus indulgéntiam consequámur."},{"k":"macro","name":"Per Dominum"}]},"hr":{"3849d1e4fb82ffed":{"t":"Ps 131, 9-10, Ps 131, 1\n(Ps 131, 9-10) Svećenici tvoji, Gospodine, neka obuku pravdu i sveti tvoji neka kliču od radosti. Radi Davida sluge svoga ne prezri lice pomazanika svoga. (Ps 131, 1) Spomeni se, Gospodine, Davida i sve revnosti njegove.\n<i>Slava Ocu, i Sinu, i Duhu Svetomu. Kako bijaše na početku, tako i sada i vazda i u vijeke vjekova. Amen</i>.\n(Ps 131, 9-10) Svećenici tvoji, Gospodine, neka obuku pravdu i sveti tvoji neka kliču od radosti. Radi Davida sluge svoga ne prezri lice pomazanika svoga.","kn":"(Ps. 131, 9-10). Svećenici se Tvoji. Gospodine, odjenuli pravdom i radovali se Tvoji sveti: poradi Davida, sluge svoga, ne odbaci pomazanika od sebe. (Ps. 131, 1.) Sjeti se, -Gospodine, Davida i sve njegove pobožnosti. Slava Ocu ... Svecemci se . . .","knRef":"Kniewald 1942, str. 602–603 (snimka 302) (OCR)"},"63bfdf3719978a5c":{"t":"<i>Pomolimo se</i>.\nBože, koji si blaženog Antuna Mariju priznavaoca svoga i biskupa uzvisio apostolskim krepostima i po njemu skupio u Crkvi nove obitelji klerika i djevica, daj, molimo, da po njegovim savjetima i opomenama, te pomoću njegovih zasluga neprestano nastojimo tražiti spasenje duša.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>."},"3de292c3086c48c6":{"t":"Heb 7, 23-27\nČitanje Poslanice bl. Pavla apostola Hebrejima. Braćo, bilo je mnogo svećenika, jer je došla smrt i nisu mogli ostati. A Isus ima vječno svećeništvo, jer ostaje zauvijek. Zato i može spašavati one koji po njem dolaze k Bogu, jer je trajno naš zagovornik. Trebao nam je upravo takav Veliki svećenik svet, nedužan, neokaljan, odijeljen od grješnika, uzvišeniji od neba. On ne treba kao drugi svećenici svakoga dana prinositi žrtve najprije za svoje grijehe, onda za grijehe naroda, jer je to učinio jedanput, kada je sama sebe prikazao naš Gospodin Isus Krist.","kn":"Čitanje poslanice sv. Pavla apostola Hebrejima (7, 23-27). Braćo! Bilo je mnogo svećenika zato, jer ih je priječila smrt, da ostanu Isus ima vječno >svećeništvo, jer ostaje do vijeka. Zato i može uvijek Spašavati, one, koji po njemu dolaze k Bogu, jer živi uvijek kao naš zagovornik. Dolikovalo je, da imamo takova velikog svećenika, koji je svet, ne- vin, neokaljan, odijeljen od grješnika i uzviSeniji od neba. Njemu ne treba, kao što to čine svećenici, da priniosii svaki dan žrtve najprije za svoje grijehe, zatim za grijehe naroda, jer je to učinio jedamput, kad je samoga sebe prikazao Isus Krist, naš Gospodin.","knRef":"Kniewald 1942, str. 810–811 (snimka 406) (OCR)"},"f6896cd108355439":{"t":"Ps 131, 16-17\nSvećenike ću njegove obući spasenjem i sveti će njegovi klicati u radosti. Ondje ću uzdignuti snagu Davidovu, pripraviti svjetiljku pomazaniku svojem.\n\nPs 109, 4\n<i>Aleluja</i>, <i>aleluja</i>.\nZakleo se Gospodin i neće se pokajati: ti si svećenik dovijeka po redu Melkisedekovu. <i>Aleluja</i>.","kn":"(Ps. 131, 16-17). Svećenike ću sionske odjenuti spasenjem i neka se vesele sdonski sveti! Odanle ću proizvesti Da vidova moćna potomka, pripravit ću svijetlo pomazaniku svome. AIcluja, aleluja.\n\nAleluja, aleluja (Ps, 109, 4). Zakle se Gospodin i ne će se pokajati: Ti si svećenik dovijeka, po redu Melkisedekovu, aleluja.","knRef":"Kniewald 1942, str. 630–631 (snimka 316) (OCR)"},"e9a47d900286fbd2":{"t":"Mt 24, 42-47\nSlijedi sveto Evanđelje po Mateju. U ono vrijeme Isus reče svojim učenicima: Bdijte, jer ne znate časa kada će doći vaš Gospodin. Pazite: Kada bi domaćin znao čas kada će doći tat, bdio bi i ne bi dopustio potkopati svoje kuće. Zato budite pripravni i vi, jer će u čas, kada vi ne slutite, doći Sin Čovječji. Tko je vjeran i razborit sluga, kojega gospodar postavlja nad svojim ukućanima, da im dade hranu u pravo vrijeme? Blago onome slugi, koga njegov gospodar kad dođe, nađe da radi tako. Zaista vam kažem: Postavit će ga nad čitavim svojim imutkom.","v":"ista misa na staroj stranici, latinski tekst odstupa (sličnost 0.98)"},"88bea9a296c140ac":{"t":"Ps 88, 25\nMoja će vjernost i moje milosrđe biti s njime, i svojim ću imenom uzdići njegovu moć.","kn":"(Ps. 88, 25). Istina je moja i milosrđe moje B njime i u ime će se moje uzdići moć njegova.","knRef":"Kniewald 1942, str. 452–453 (snimka 227) (OCR)"},"fb0db106d2421803":{"t":"Neka nas godišnja svetkovina svetoga Antuna Marije tvoga priznavaoca i biskupa učini, molimo, Gospodine, dragima tvojoj očinskoj dobroti da po ovoj pobožnoj pomirbenoj službi njega prati blažena nagrada i nama udijeli tvoje milosne darove.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Molimo, Gospodine, neka nas godišnja svetkovina svetoga I., priznavaoca Tvoga, omili dobroti Tvojoj, da ova pobožna zadovoljština umnoži njegovu nagradu i nama pribavi darove Tvoje milosti, po G. n.","knRef":"Kniewald 1942, str. 812–813 (snimka 407) (OCR)"},"404159d2e4df1ef4":{"t":"Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda i svagdje zahvaljujemo tebi, Gospodine, sveti Oče, svemogući vječni Bože, po Kristu Gospodinu našemu. – Po njemu tvoje veličanstvo hvale anđeli, klanjaju se gospodstva i dršću vlasti. Nebesa i nebeske sile i blaženi serafini zajedničkim klicanjem slave. Daj, molimo, s njima i naše glase primi dok govorimo poniznim hvalospjevom:","kn":"Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda i svagdje zahvaljujemo Tebi, Gospodine sveti. Oče svemogući, vječni Bože, po Kristu, Gospotdiniu našemu, po kome veličanstvo Tvoje hvale anđeli, klanjaju Ti se gospodstva, tresu se vlasti. Nebesa Te i nebeske moći i blaženi serafini, zadružnim klicanjem zajedno slave. Zapovijedi, molimo, da se i naši glasovi združe s njihovima, smjernim isippvijedanjem govoreći:","knRef":"Kniewald 1942, str. 18–19 (snimka 10) (OCR)"},"56842ed674d6e163":{"t":"Mt 24, 46-47\nBlago slugi koga gospodar nađe budna, kad dođe. Zaista vam kažem: Postavit će ga nad svim imanjem svojim.","kn":"(Mt. 24, 46-47). Blago onomu slugi, koga nađe njegov gospodar budna, kad dođe! zaista vam kažem, da će ga postaviti nad svim imanjem svojim.","knRef":"Kniewald 1942, str. 816–817 (snimka 409) (OCR)"},"1764f3a5bdbf8fa9":{"t":"<i>Pomolimo se</i>.\nBože, koji nagrađuješ duše vjernih daj da postignemo oproštenje po molitvama blaženog Antuna Marije tvoga priznavaoca i biskupa kojega časnu svetkovinu slavimo.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Bože, koji nagrađuješ vjerne duše, podaj, da zadobijemo oproštenje molbama blaženoga I., Tvoga priznavaoca i biskupa, kojega slavimo časnu svetkovinu, po G. n.","knRef":"Kniewald 1942, str. 812–813 (snimka 407) (OCR)"}}});
